sn_vsc_security_check_configurations.config_evaluation_script:
// Query to see if any MID Servers are configured
var scComplianceUtil = new sn_vsc.VSCComplianceUtil();
if (new GlidePluginManager().isActive('com.glideapp.agent')) {
    var gr1 = new GlideRecord('ecc_agent');
    gr1.query();
    // Query for MID Server Property alias_filtering_behavior
    var gr2 = new GlideRecord('ecc_agent_property');
    gr2.addEncodedQuery('name=alias_filtering_behavior^value=strict');
    gr2.query();
    var grConfig = new GlideRecord('sn_vsc_security_check_configurations');
    grConfig.get('config_name', 'alias_filtering_behavior');
    grConfig.config_configure = true;
    // Check to make sure MID Server functionality is utilized before returning a finding
    // If the property table record does not exit, then default is loose, which is a finding
    if (gr1.next() && !gr2.next()) {
        grConfig.config_configure = false;
    }
    grConfig.update();
    // update related hardening settings
    var settingArr = grConfig.config_setting.split(",");
    scComplianceUtil.updateSettingCompliance(settingArr);
} else {
    scComplianceUtil.setConfigCompliantByDefault('alias_filtering_behavior', 'alias_filtering_behavior', 'strict');
}

