sn_vsc_security_check_configurations.config_evaluation_script:
var defaultVal = '';
var targetProperty = 'com.glide.cs.embed.xframe_options';
var propVal = gs.getProperty(targetProperty, defaultVal);

var grConfig = new GlideRecord('sn_vsc_security_check_configurations');
grConfig.get('config_name', targetProperty);

grConfig.config_configure = (propVal != null && (propVal == 'deny' || propVal == 'sameorigin')) ? true : false;
grConfig.config_current_value = propVal;
grConfig.update();

// update related hardening settings
var settingArr = grConfig.config_setting.split(",");
new sn_vsc.VSCComplianceUtil().updateSettingCompliance(settingArr);

var grConfig = new GlideRecord('sn_vsc_security_check_configurations');
grConfig.get('config_name', 'com.glide.email_filter');
var dependentProp = gs.getProperty('glide.email.read.active', 'true');
if (dependentProp.toLowerCase() == 'true') {
    grConfig.config_configure = GlidePluginManager.isActive('com.glide.email_filter');
} else {
    grConfig.config_configure = true;
}
grConfig.update();
var settingArr = grConfig.config_setting.split(","); //Each configuration can belong to multiple settings
new sn_vsc.VSCComplianceUtil().updateSettingCompliance(settingArr);

