sn_vsc_security_check_configurations.config_evaluation_script:
if (new GlidePluginManager().isActive('com.sn_em_connector')) {
    var defaultVal = "admin,evt_mgmt_admin,sn_sow_srm.srm_admin";
    var recValue = "admin,evt_mgmt_admin,sn_sow_srm.srm_admin";
    new sn_vsc.VSCComplianceUtil().evaluateTextValues('evt_mgmt.connector_assignment_group_admin_roles', recValue, defaultVal);
} else {
    new sn_vsc.VSCComplianceUtil().setConfigCompliantByDefault('evt_mgmt.connector_assignment_group_admin_roles', 'evt_mgmt.connector_assignment_group_admin_roles', defaultVal);
}

var targetProperty = 'glide.active.session.timeout.exception.roles';
var expectedValue = 'edge_encryption,mid_server';
var defaultValue = 'edge_encryption,mid_server';
var propertyValue = gs.getProperty(targetProperty, defaultValue);

var expectedValueList = expectedValue.split(',');
var propertyValueList = propertyValue.split(',');
var grConfig = new GlideRecord('sn_vsc_security_check_configurations');
grConfig.get('config_name', targetProperty);
grConfig.config_configure = true;
//Trigger a finding if a role outside the expected 2 roles is included
for (i = 0; i < propertyValueList.length; i++) {
    if (expectedValueList.indexOf(propertyValueList[i]) == -1) {
        grConfig.config_configure = false;
        break;
    }
}
grConfig.update();
// update related hardening settings
var settingArr = grConfig.config_setting.split(",");
new sn_vsc.VSCComplianceUtil().updateSettingCompliance(settingArr);

var propName = 'glide.authenticate.limit.concurrent.interactive.sessions';
var configName = 'glide.authenticate.limit.concurrent.interactive.sessions';
