    var grConfig = new GlideRecord('sn_vsc_security_check_configurations');
    grConfig.get('config_name', 'glide.authenticate.session_access.mobile.refresh_token_interval');
    grConfig.config_configure = isNaN(propertyValue) || parseInt(propertyValue, 10) > expectedValue ? false : true;
    grConfig.config_current_value = propVal;
    grConfig.update();
    // update related hardening settings
    var settingArr = grConfig.config_setting.split(",");
    new sn_vsc.VSCComplianceUtil().updateSettingCompliance(settingArr);
} else {
    new sn_vsc.VSCComplianceUtil().setConfigCompliantByDefault('glide.authenticate.session_access.mobile.refresh_token_interval', 'glide.authenticate.session_access.mobile.refresh_token_interval', defaultVal);
}

var defaultVal = 'false';
var scComplianceUtil = new sn_vsc.VSCComplianceUtil();
var targetProperty = "glide.authenticate.sso.saml2.enable_relay_state_with_id";
if (new GlidePluginManager().isActive('com.snc.integration.sso.multi.installer')) {
    scComplianceUtil.evaluateCompliance(targetProperty, 'true', defaultVal);
} else {
    scComplianceUtil.setConfigCompliantByDefault(targetProperty, targetProperty, defaultVal);
}

var targetProperty = 'glide.authenticate.sso.saml2.keystore';

var grConfig = new GlideRecord('sn_vsc_security_check_configurations');
grConfig.get('config_name', targetProperty);
grConfig.config_configure = true;

var pluginManager = new GlidePluginManager();
if (pluginManager.isActive('com.snc.integration.sso.multi.installer')) {
var keystore_id = gs.getProperty(targetProperty, '');

var flagged_values = ['require_signed_authnrequest', 'require_signed_logoutrequest', 'encrypt_assertion'];

// table exists only when plugin "com.snc.integration.sso.multi.installer" is active
if (gs.tableExists('saml2_update1_properties')) {
var saml_props = new GlideRecord('saml2_update1_properties');
saml_props.addActiveQuery();
saml_props.query();

// Only process records where SAML IDP is active
while (saml_props.next()) {

	// Only check if one of flagged values is true
	flagged_value_true = 'false';
	for (i in flagged_values) {
		if (saml_props[flagged_values[i]].toLowerCase() == 'true') {
			flagged_value_true = 'true';
		}
	}

	if (flagged_value_true.toLowerCase() == 'true') {

		// keystore_id is the property value, Only check if the sys_id is one of two demo data X.509 Certificates
		if (keystore_id == 'c60ad24b732220103a5b0dd43cf6a7db' || keystore_id == '3685fc22930212003c5537ae867ffb91') {
			var attachment = new GlideSysAttachment();
			cert_meta = attachment.getAttachments('sys_certificate', keystore_id);

			if (cert_meta.next()) {
				file_name = cert_meta['file_name'];
				file_hash = cert_meta['hash'];
				file_sys_id = cert_meta['sys_id'];
				file_size = cert_meta['size_bytes'];

				// Check for Demo value 1 with hash or Check for Demo value 2 with name, size, sys id (no hash)
				if ((keystore_id == 'c60ad24b732220103a5b0dd43cf6a7db' && file_hash == 'b2a36b7b894e51c5293461b4cda0eaa7c6cd90b4f4ddfb9520e0339a119a92e9') ||
					(keystore_id == '3685fc22930212003c5537ae867ffb91' && file_name == 'saml2sp_key2048withsha256.jks' && file_sys_id == 'cfe67062930212003c5537ae867ffb66' && file_size == 2286)) {
					grConfig.config_configure = false;
					break;
				}
			}
		}
	}
}
}
}
grConfig.config_current_value = keystore_id;
grConfig.update();

// update related hardening settings
var settingArr = grConfig.config_setting.split(",");
new sn_vsc.VSCComplianceUtil().updateSettingCompliance(settingArr);

