var defaultVal = 'text/html,image/svg,image/svg+xml,application/xml';
var targetProperty = 'glide.ui.attachment.download_mime_types';
var scUtil = new sn_vsc.VSCComplianceUtil();

var forceDownloadConfigured = gs.getProperty('glide.ui.attachment.force_download_all_mime_types', 'false');
// Only bother with the check if force download is not configured.
if (forceDownloadConfigured.toLowerCase() == "false") {
    var grConfig = new GlideRecord('sn_vsc_security_check_configurations');
    grConfig.get('config_name', targetProperty);
    var value_dict = {
        'text/html': '',
        'image/svg': '',
        'image/svg+xml': '',
        'application/xml': ''
    };
    var requiredValueList = JSON.parse(JSON.stringify(value_dict));
    var rawValue = gs.getProperty(targetProperty, defaultVal);
    var valueArray = rawValue.split(',');
    for (var i = 0; i < valueArray.length; i++) {
        var current = valueArray[i];
        if (requiredValueList.hasOwnProperty(current))
            delete requiredValueList[current];
    }
    if (Object.keys(requiredValueList).length != 0) {
        grConfig.config_configure = false;
    } else {
        grConfig.config_configure = true;
    }
    grConfig.config_current_value = rawValue;
    var settingArr = grConfig.config_setting.split(","); //Each dependency can belong to multiple configurations
    grConfig.update();
    scUtil.updateSettingCompliance(settingArr);
} else {
    scUtil.setConfigCompliantByDefault(targetProperty, targetProperty, defaultVal);
}

