sn_vsc_security_check_configurations.config_evaluation_script:
var defaultVal = 'connectionFactory, queueConnectionFactory, topicConnectionFactory';
var scComplianceUtil = new sn_vsc.VSCComplianceUtil();
if (new GlidePluginManager().isActive('com.snc.runbook_automation.runtime')) {
    var grConfig = new GlideRecord('sn_vsc_security_check_configurations');
    if (grConfig.get('config_name', 'mid.property.jms.command.allowed_factory_names')) {
        grConfig.config_configure = true;
        var gr = new GlideRecord('ecc_agent_property');
        gr.addEncodedQuery('name=mid.property.jms.command.allowed_factory_names');
        gr.query();
        if (gr.next()) {
            var propVal = gr.getValue('value');
            var propValArr = propVal.split(',');
            for (i = 0; i < propValArr.length; i++) {
                if (!defaultVal.includes(propValArr[i])) {
                    grConfig.config_configure = false;
                    break;
                }
            }
            grConfig.config_current_value = propVal;
        }
		grConfig.update();
		// update related hardening settings
		var settingArr = grConfig.config_setting.split(",");
		scComplianceUtil.updateSettingCompliance(settingArr);
    }
} else {
    scComplianceUtil.setConfigCompliantByDefault('mid.property.jms.command.allowed_factory_names', 'mid.property.jms.command.allowed_factory_names', defaultVal);
}

